begin;
select no_plan();
insert into auth.users (id, email) values ('00000000-0000-0000-0000-0000000000a6', 'sa6@dev.test');
insert into public.profiles (user_id, full_name, role) values ('00000000-0000-0000-0000-0000000000a6', 'Super Six', 'super_admin');
insert into public.customers (id, full_name, phone_e164, whatsapp_opt_in_at) values ('00000000-0000-0000-0000-00000000c014', 'Wa Person', '+971500000614', now());
insert into public.messages (idempotency_key, customer_id, channel, provider, to_address, template_key, body, status, provider_id) values ('wa-key-1', '00000000-0000-0000-0000-00000000c014', 'whatsapp', 'whatsapp_cloud', '+971500000614', 'enquiry_received_wa', 'hi', 'sent', 'wamid.AAA');
select set_config('request.jwt.claims', '{"role":"service_role"}', true);
set local role service_role;
select is((select public.apply_whatsapp_status('e1', 'wamid.AAA', 'delivered')), 'updated', 'WAH-001 a delivery receipt moves the message forward');
select is((select public.apply_whatsapp_status('e1', 'wamid.AAA', 'delivered')), 'duplicate_event', 'WAH-002 a replayed receipt is ignored');
select is((select public.apply_whatsapp_status('e2', 'wamid.AAA', 'sent')), 'ignored', 'WAH-003 a late sent receipt does not move it back');
select is((select public.apply_whatsapp_status('e3', 'wamid.AAA', 'failed', 'x')), 'ignored', 'WAH-004 a failure never overrides a delivered message');
select is((select public.apply_whatsapp_status('e4', 'wamid.AAA', 'read')), 'updated', 'WAH-005 read follows delivered');
select is((select public.apply_whatsapp_status('e5', 'wamid.unknown', 'read')), 'unknown_message', 'WAH-006 unknown messages are acknowledged');
select is((select public.record_whatsapp_inbound('i1', '971500000614', ' STOP ')), 'opted_out', 'WAH-007 STOP withdraws consent');
select is((select public.record_whatsapp_inbound('i2', '971500000614', 'Is Max still available?')), 'forwarded', 'WAH-008 other replies go to staff');
select is((select public.record_whatsapp_inbound('i3', '971500000999', 'Hello')), 'forwarded_unknown', 'WAH-009 unknown numbers are forwarded too');
select is((select public.record_whatsapp_inbound('i4', '971500000614', 'start')), 'opted_in', 'WAH-010 START restores consent for someone who had opted in');
select is((select public.record_whatsapp_inbound('i1', '971500000614', 'stop')), 'duplicate_event', 'WAH-011 a replayed inbound message is ignored');
reset role;
select is((select status::text from public.messages where idempotency_key = 'wa-key-1'), 'read', 'WAH-012 the log shows the furthest status');
select is((select whatsapp_opted_out_at is null from public.customers where id = '00000000-0000-0000-0000-00000000c014'), true, 'WAH-013 consent is restored after START');
select is((select count(*)::int from public.notifications where user_id = '00000000-0000-0000-0000-0000000000a6' and title like 'WhatsApp message from%'), 2, 'WAH-014 staff were notified of the two replies');
set local role authenticated;
select throws_ok($$select public.record_whatsapp_inbound('z', '1', 'x')$$, '42501', null, 'WAH-015 only the service role can apply webhooks');
select * from finish();
rollback;
